const EYE = (x, y, r = 9) => [C(x, y, r, WH), DOT(x, y + 1, r / 2)];
const STAR5 = (cx, cy, R1, R2, fill) => { const p = []; for (let i = 0; i < 10; i++) { const a = -Math.PI / 2 + i * Math.PI / 5, r = i % 2 ? R2 : R1; p.push(`${f(cx + r * Math.cos(a))},${f(cy + r * Math.sin(a))}`); } return G(p.join(' '), fill); };
